import { compareWorkspaceFixture } from '../../support/compareWorkspace.ts';
import { WorkspaceRecordStore } from '../../../infrastructure/mapping/persistence/workspace/workspaceRecordStore.ts';
// npm run build && CHROME_PATH=... node --import tsx tests/browser/mapping/browser-experiments-check.mjs
import assert from 'node:assert/strict';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { spawn } from 'node:child_process';
import { createServer } from 'node:net';
import { chromium, expect } from '@playwright/test';
import { seedMappingFixture } from '../support/browser-mapping-fixture.mjs';
import { AgentContextLibrary } from '../../../application/mapping/agent/agentContextLibrary.ts';
import { FileAgentContextRepository } from '../../../infrastructure/core/persistence/fileAgentContextRepository.ts';
const root = await mkdtemp(path.join(tmpdir(), 'experiments-browser-'));
let server, browser;
try {
  await seedMappingFixture(root, { ascii: 'Domain\n`-- Shared feature', nodes: [] });
  const store = path.join(root, '.diagrams');
  const { id: projectId } = JSON.parse(await readFile(path.join(store, 'project.json'), 'utf8'));
  await new WorkspaceRecordStore(store).state(projectId, async () => compareWorkspaceFixture(projectId));
  const contexts = new AgentContextLibrary(new FileAgentContextRepository(store));
  const inputs = await Promise.all(['Input one', 'Input two'].map(name => contexts.create({ requestId: crypto.randomUUID(), name, context: 'A repository with a domain and a storage service.' })));
  const port = await new Promise(resolve => { const socket = createServer(); socket.listen(0, '127.0.0.1', () => { const port = socket.address().port; socket.close(() => resolve(port)); }); });
  const base = `http://127.0.0.1:${port}`;
  server = spawn(process.execPath, ['scripts/dev/start-server.mjs', 'preview', '--host', '127.0.0.1', '--port', String(port), '--strictPort'], { env: { ...process.env, NEW_DIAGRAM_PROJECT_ROOT: root, NEW_DIAGRAMS_DIR: store, NEW_DIAGRAM_AGENT: 'fake' }, stdio: ['ignore', 'pipe', 'pipe'] });
  let log = ''; server.stdout.on('data', b => { log += b; }); server.stderr.on('data', b => { log += b; });
  await expect.poll(async () => (await fetch(base).catch(() => null))?.status, { timeout: 30000 }).toBe(200);
  const api = async (route, body) => { const res = await fetch(base + route, body ? { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) } : undefined); const value = await res.json(); assert(res.ok, JSON.stringify(value)); return value; };
  const e = '/api/mapping/evals';
  const prompt = await api(e + '/prompts', { requestId: crypto.randomUUID(), workflow: 'alternatives', name: 'Fixture prompt', stages: { alternative: 'Read context.json. Generate ASCII trees with the supplied JSON output schema.' } });
  const variationPrompt = await api(e + '/prompts', { requestId: crypto.randomUUID(), workflow: 'alternatives', name: 'Code variation', stages: { alternative: prompt.versions[0].stages.alternative + '\nUse code expressions.' }, derivation: { parent: { promptId: prompt.id, version: 1 }, kind: 'variation', dimension: { id: 'expression', name: 'Expression', value: '100% code / 0% natural language' } } });
  const generate = async (context, passes, selectedPrompt = prompt) => {
    const run = await api(e + '/runs', { requestId: crypto.randomUUID(), workflow: 'alternatives', prompts: [{ promptId: selectedPrompt.id, version: 1 }], inputs: { context: { agentContextId: context.agentContextId } }, passes, model: 'test-model', effort: 'high' });
    await expect.poll(async () => (await api(e + '/runs/' + run.id)).status, { timeout: 30000 }).toBe('finished'); return api(e + '/runs/' + run.id);
  };
  const baseline = await generate(inputs[0], 3), variant = await generate(inputs[0], 1, variationPrompt);
  const chain1 = await generate(inputs[0], 3), chain2 = await generate(inputs[1], 3), legacy = await generate(inputs[1], 1);
  const source = cell => ({ documentId: cell.canvasId, checkpointId: cell.checkpointId });
  const sources = [...baseline.cells, ...variant.cells].map(source);
  const comparison = await api('/api/mapping/comparison-runs', { requestId: crypto.randomUUID(), title: 'Expression assessment', sources, experiment: { baseline: baseline.cells.map(source), prompted: variant.cells.map(source), promptDifference: 'Expression changes.', controlledSettings: 'Same pinned input.', maxComparisons: 2 } });
  await expect.poll(async () => (await api('/api/mapping/comparison-runs/' + comparison.id)).status, { timeout: 30000 }).toBe('finished');
  const secondComparison = await api('/api/mapping/comparison-runs', { requestId: crypto.randomUUID(), title: 'Second assessment', sources, experiment: { baseline: baseline.cells.map(source), prompted: variant.cells.map(source), promptDifference: 'Expression changes.', controlledSettings: 'Same pinned input.', maxComparisons: 2 } });
  await expect.poll(async () => (await api('/api/mapping/comparison-runs/' + secondComparison.id)).status, { timeout: 30000 }).toBe('finished');
  const judgementId = comparison.id + '-report', secondJudgementId = secondComparison.id + '-report'; await api(e + '/judgements');
  const cases = inputs.map((c, i) => ({ id: `input-${i}`, name: c.name, agentContextId: c.agentContextId, contentHash: c.contentHash }));
  const sample = (run, cell, conditionId, number) => ({ id: `${conditionId}-${number}`, caseId: cases[0].id, conditionId, number, attempt: 1, outputs: [{ stageId: 'generate', runId: run.id, cellKey: cell.key }] });
  const styles = await api(e + '/experiments', { requestId: crypto.randomUUID(), experiment: { name: 'Style controls', description: 'Three shared controls and one extreme.', workflow: { id: 'alternatives', name: 'Generate canvas', version: 1, stages: [{ id: 'generate', name: 'Generate canvas', dependsOn: [] }] }, cases: [cases[0]], conditions: [{ id: 'baseline', name: 'Shared baseline' }, { id: 'code', name: 'Code' }], samples: [...baseline.cells.map(c => sample(baseline, c, 'baseline', c.pass)), ...variant.cells.map(c => sample(variant, c, 'code', c.pass))], comparisons: [{ id: 'expression', name: 'Code vs language', conditionIds: ['baseline', 'code'], caseIds: [cases[0].id], judgementIds: [judgementId] }, { id: 'second', name: 'Second assessment', conditionIds: ['baseline', 'code'], caseIds: [cases[0].id], judgementIds: [secondJudgementId] }] } });
  const stages = [{ id: 'modify', name: 'Modify existing', dependsOn: [] }, { id: 'c1', name: 'Generate C1', dependsOn: ['modify'] }, { id: 'c2', name: 'Generate C2 cluster', dependsOn: ['c1'] }];
  const chain = await api(e + '/experiments', { requestId: crypto.randomUUID(), experiment: { name: 'Chained generation', workflow: { id: 'chain', name: 'Three-stage workflow', version: 1, stages }, cases, conditions: [{ id: 'baseline', name: 'Baseline' }], samples: [chain1, chain2].map((run, i) => ({ id: `sample-${i}`, caseId: cases[i].id, conditionId: 'baseline', number: 1, outputs: run.cells.map((cell, n) => ({ stageId: stages[n].id, runId: run.id, cellKey: cell.key })) })), comparisons: [] } });
  const before = await api(e + '/experiments');
  browser = await chromium.launch({ headless: true, ...(process.env.CHROME_PATH ? { executablePath: process.env.CHROME_PATH } : {}), args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1396, height: 632 } }); const errors = [];
  page.on('pageerror', error => errors.push(error.message));
  await page.goto(`${base}/evals?experiment=${styles.id}`);
  await expect(page.getByRole('heading', { name: 'Style controls', exact: true })).toBeVisible();
  const explorer = page.locator('.experiment-explorer');
  await expect(explorer.getByRole('button', { name: 'Code vs language', exact: true })).toHaveCount(1);
  await explorer.getByRole('button', { name: /Shared baseline/ }).click();
  const outputNav = page.getByRole('navigation', { name: 'Output navigation' });
  await expect(page).toHaveURL(new RegExp(`run=${baseline.id}`));
  await expect(page.locator('.output-view').getByRole('application', { name: 'tldraw' })).toBeVisible();
  await expect(outputNav).toContainText('1 / 4');
  await expect(outputNav.getByRole('button', { name: 'Previous output' })).toBeDisabled();
  for (const position of [2, 3, 4]) {
    await page.keyboard.press('ArrowRight'); await expect(outputNav).toContainText(`${position} / 4`);
  }
  await expect(page).toHaveURL(new RegExp(`run=${variant.id}`));
  await expect(outputNav.getByRole('button', { name: 'Next output' })).toBeDisabled();
  await page.keyboard.press('ArrowLeft'); await expect(outputNav).toContainText('3 / 4');
  await expect(page).toHaveURL(new RegExp(`run=${baseline.id}`));
  await page.locator('.experiment-breadcrumb').getByRole('button', { name: 'All outputs' }).click();
  await expect(page.getByRole('table', { name: 'Workflow outputs' }).getByRole('row')).toHaveCount(5);
  await page.getByRole('checkbox', { name: 'Select Shared baseline · sample 1 · Generate canvas for comparison' }).check();
  await page.getByRole('checkbox', { name: 'Select Code · sample 1 · Generate canvas for comparison' }).check();
  await expect(page.getByRole('region', { name: 'Compare selected outputs' })).toContainText('2 selected');
  await page.getByRole('button', { name: 'Clear', exact: true }).click();
  await explorer.getByRole('button', { name: 'Code vs language', exact: true }).click();
  await expect(page.locator('.comparison-report')).toBeVisible();
  await expect(page.locator('.experiment-breadcrumb')).toContainText('Style controls');
  await expect(page.getByRole('button', { name: 'Previous finding' })).toBeDisabled();
  // Text pages participate in traversal, then findings continue into the next report.
  await page.keyboard.press('ArrowRight'); await expect(page.getByText('Finding 1 of 2', { exact: true })).toBeVisible();
  await page.keyboard.press('ArrowRight'); await expect(page.getByText('Finding 2 of 2', { exact: true })).toBeVisible();
  await page.keyboard.press('ArrowRight');
  await expect(page.getByLabel('Judgement', { exact: true })).toHaveValue(secondJudgementId);
  await expect(page.getByLabel('Report page', { exact: true })).toHaveValue('0');
  await page.keyboard.press('ArrowLeft');
  await expect(page.getByLabel('Judgement', { exact: true })).toHaveValue(judgementId);
  await expect(page.getByText('Finding 2 of 2', { exact: true })).toBeVisible();
  await page.reload(); await expect(page.getByText('Finding 2 of 2', { exact: true })).toBeVisible();
  // Select controls retain their own keyboard interaction.
  await page.getByLabel('Report page', { exact: true }).focus();
  await page.keyboard.press('ArrowRight');
  await expect(page.getByLabel('Judgement', { exact: true })).toHaveValue(judgementId);
  assert((await page.locator('.comparison-report-panes').boundingBox()).height > 300, 'Compact layout should leave at least 300px for panes');
  await expect(page.locator('.evals-header-more')).toBeVisible();
  await expect(page.locator('.comparison-page-tab').first()).toBeHidden();
  if (process.env.EVALS_SCREENSHOTS) await page.screenshot({ path: path.join(process.env.EVALS_SCREENSHOTS, 'experiments-compact.png') });
  await explorer.getByRole('button', { name: /Input two/ }).click();
  await expect(page).toHaveURL(new RegExp(`run=${chain2.id}`));
  await expect(outputNav).toContainText('4 / 6');
  await page.keyboard.press('ArrowLeft'); await expect(outputNav).toContainText('3 / 6');
  await expect(page).toHaveURL(new RegExp(`run=${chain1.id}`));
  await page.keyboard.press('ArrowRight'); await expect(outputNav).toContainText('4 / 6');
  await expect(page).toHaveURL(new RegExp(`run=${chain2.id}`));
  await expect(page.locator('.experiment-breadcrumb')).toContainText('Chained generation');
  await page.locator('.experiment-breadcrumb').getByRole('button', { name: 'All outputs' }).click();
  const matrix = page.getByRole('table', { name: 'Workflow outputs' });
  await expect(matrix.getByRole('columnheader')).toHaveCount(4); await expect(matrix.getByRole('row')).toHaveCount(3);
  await expect(matrix.getByRole('columnheader', { name: 'Generate C2 cluster' })).toBeVisible();
  await page.locator('.experiment-legacy > summary').click();
  await expect(page.getByRole('button', { name: new RegExp(`^Run #${legacy.number} ·`) })).toBeVisible();
  await expect(page.getByRole('button', { name: new RegExp(`^Run #${baseline.number} ·`) })).toHaveCount(0);
  await page.setViewportSize({ width: 1024, height: 640 });
  await explorer.getByRole('button', { name: 'Code vs language', exact: true }).click();
  await page.getByLabel('Report page', { exact: true }).selectOption('1');
  await page.getByRole('button', { name: 'Expand comparison', exact: true }).click();
  assert((await page.locator('.comparison-report-panes').boundingBox()).height > 300);
  assert.deepEqual(await api(e + '/experiments'), before, 'Viewer interactions must not change saved experiments');
  const beforeReviewRuns = await api(e + '/runs');
  const plannedRunId = crypto.randomUUID();
  const planned = await api(e + '/experiments', { requestId: crypto.randomUUID(), experiment: {
    name: 'Diagram split approval', description: 'Review fixture', workflow: { id: 'alternatives', name: 'Split diagram', version: 1, stages: [{ id: 'generate', name: 'Generate canvas', dependsOn: [] }] },
    cases: [cases[0]], conditions: [{ id: 'baseline', name: 'Baseline' }], comparisons: [],
    samples: [1,2,3].map(number => ({ id: `review-${number}`, caseId: cases[0].id, conditionId: 'baseline', number, outputs: [] })),
    plannedRuns: [{ request: { requestId: plannedRunId, workflow: 'alternatives', prompts: [{ promptId: prompt.id, version: 1 }], inputs: { context: { agentContextId: inputs[0].agentContextId } }, passes: 3, model: 'gpt-6-astra', effort: 'high' },
      outputs: [1,2,3].map(number => ({ sampleId: `review-${number}`, stageId: 'generate', cellKey: `${prompt.id}:${number}:alternative` })) }]
  } });
  assert.deepEqual(await api(e + '/runs'), beforeReviewRuns, 'Preparing an experiment must not start generation');
  await page.setViewportSize({ width: 1396, height: 632 });
  await page.goto(`${base}/evals?experiment=${planned.id}`);
  const review = page.getByRole('region', { name: 'Generation review' });
  await expect(review).toContainText('Generation has not started');
  await expect(review).toContainText(prompt.versions[0].stages.alternative);
  await expect(review).toContainText('3 planned outputs');
  await expect(review).toContainText('gpt-6-astra / high');
  const approve = review.getByRole('button', { name: 'Approve and start generation' });
  await expect(approve).toBeDisabled();
  await page.reload();
  await expect(approve).toBeDisabled();
  assert.deepEqual(await api(e + '/runs'), beforeReviewRuns, 'Reloading review must not launch');
  await expect(review.getByRole('button', { name: 'Collapsible sections' })).toHaveCount(0);
  const pinnedFontSize = await review.getByLabel('alternative pinned prompt').evaluate(el => parseFloat(getComputedStyle(el).fontSize));
  await review.getByRole('button', { name: 'Edit section', exact: true }).click();
  const editModal = page.getByRole('dialog', { name: 'Edit alternative section', exact: true });
  const editField = editModal.getByLabel('alternative section', { exact: true });
  await expect(editModal).toBeVisible();
  await expect(editField).toBeFocused();
  const editFontSize = await editField.evaluate(el => parseFloat(getComputedStyle(el).fontSize));
  assert(Math.abs(editFontSize - pinnedFontSize - 4 * 96 / 72) < 0.01, 'Modal font grows by 4pt');
  assert.equal(await editModal.locator('.template-editor pre').evaluate(el => parseFloat(getComputedStyle(el).fontSize)), editFontSize, 'Highlighted mirror matches textarea font');
  const modalFont = () => editField.evaluate(el => parseFloat(getComputedStyle(el).fontSize));
  await page.keyboard.press('Control+=');
  await expect.poll(async () => Math.abs(await modalFont() - editFontSize - 96 / 72) < 0.01).toBe(true);
  await page.keyboard.press('Control+Shift+=');
  await expect.poll(async () => Math.abs(await modalFont() - editFontSize - 2 * 96 / 72) < 0.01).toBe(true);
  assert.equal(await editModal.locator('.template-editor pre').evaluate(el => parseFloat(getComputedStyle(el).fontSize)), await modalFont());
  await page.keyboard.press('Control+-');
  await page.keyboard.press('Control+-');
  await expect.poll(modalFont).toBe(editFontSize);
  await expect(editField).toHaveValue(prompt.versions[0].stages.alternative);
  assert.equal(await review.getByLabel('alternative pinned prompt').evaluate(el => parseFloat(getComputedStyle(el).fontSize)), pinnedFontSize, 'Font shortcuts affect only the modal editor');
  const modalBounds = await editModal.boundingBox();
  assert(modalBounds.x >= 0 && modalBounds.y >= 0 && modalBounds.x + modalBounds.width <= 1396 && modalBounds.y + modalBounds.height <= 632, 'Modal fits smaller viewport');
  await editField.fill('Discard this edit.');
  await editModal.getByRole('button', { name: 'Cancel edit' }).click();
  await expect(editModal).toHaveCount(0);
  await expect(review.getByRole('button', { name: 'Edit section', exact: true })).toBeFocused();
  await expect(review.getByLabel('alternative pinned prompt')).toHaveValue(prompt.versions[0].stages.alternative);
  await review.getByRole('button', { name: 'Edit section', exact: true }).click();
  await page.keyboard.press('Escape');
  await expect(editModal).toHaveCount(0);
  await review.getByRole('button', { name: 'Edit section', exact: true }).click();
  let revisedText = prompt.versions[0].stages.alternative + '\n<task>Preserve the seed relationships.</task>';
  await editField.fill('<unsupported>Invalid section</unsupported>');
  await page.keyboard.press('Control+s');
  await expect(editModal.getByRole('alert').first()).toContainText('unsupported');
  await expect(editModal).toBeVisible();
  await editField.fill(revisedText);
  if (process.env.EVALS_SCREENSHOTS) await page.screenshot({ path: path.join(process.env.EVALS_SCREENSHOTS, 'prompt-section-modal.png') });
  await page.keyboard.press('Control+s');
  await expect(editModal.getByRole('status')).toHaveText('Saved');
  await expect(editField).toBeFocused();
  const firstSavedVersion = (await api(e + '/prompts/' + prompt.id)).versions.at(-1).version;
  // Keep editing the same modal after the experiment and prompt versions advance.
  revisedText += '\nKeep source ownership explicit.';
  await editField.fill(revisedText);
  await expect(editModal.getByRole('status')).toBeEmpty();
  await page.keyboard.press('Control+s');
  await expect(editModal.getByRole('status')).toHaveText('Saved');
  await expect(editField).toBeFocused();
  assert.equal((await api(e + '/prompts/' + prompt.id)).versions.at(-1).version, firstSavedVersion + 1);
  if (process.env.EVALS_SCREENSHOTS) await page.screenshot({ path: path.join(process.env.EVALS_SCREENSHOTS, 'prompt-section-saved.png') });
  await editModal.getByRole('button', { name: 'Save section' }).click();
  await expect(editModal).toHaveCount(0);
  await expect(review.getByLabel('alternative pinned prompt')).toHaveValue(revisedText);
  assert.deepEqual(await api(e + '/runs'), beforeReviewRuns, 'Saving a review edit must not start generation');
  await page.reload();
  await expect(review.getByLabel('alternative pinned prompt')).toHaveValue(revisedText);
  await expect(approve).toBeDisabled();
  await review.getByRole('checkbox').check(); await approve.click();
  await expect(review).toContainText('Generation was approved and started');
  await expect.poll(async () => (await api(e + '/runs/' + plannedRunId)).status).toBe('finished');
  assert.equal((await api(e + '/runs/' + plannedRunId)).prompts[0].stages.alternative, revisedText, 'Approval uses the edited prompt');
  const approvedExperiment = await api(e + '/experiments/' + planned.id);
  assert.equal(approvedExperiment.samples.flatMap(sample => sample.outputs).length, 3);
  assert.equal((await api(e + '/runs')).length, beforeReviewRuns.length + 1);
  assert.deepEqual(errors, []);
  if (process.env.EVALS_SCREENSHOTS) await page.screenshot({ path: path.join(process.env.EVALS_SCREENSHOTS, 'experiments-browser.png') });
  // A newer catalog prompt must not replace the text pinned to an existing output.
  const originalPrompt = prompt.versions[0].stages.alternative;
  const catalogVersion = (await api(e + '/prompts/' + prompt.id)).versions.at(-1).version;
  await api(e + '/prompts', { requestId: crypto.randomUUID(), promptId: prompt.id, baseVersion: catalogVersion, workflow: 'alternatives', name: prompt.name, stages: { alternative: originalPrompt + '\nNew catalog version.' } });
  const beforeRelaunchRuns = await api(e + '/runs');
  await page.goto(`${base}/evals?experiment=${styles.id}`);
  const promptSection = page.getByRole('region', { name: 'Generation prompts' });
  await expect(promptSection.getByText('Expression', { exact: true })).toBeVisible();
  await expect(promptSection).toContainText('Shared baseline [3 outputs]');
  await expect(page.getByRole('heading', { name: 'Experimental design' })).toHaveCount(0);
  await expect(page.getByRole('table', { name: 'Workflow outputs' })).toHaveCount(0);
  assert((await promptSection.boundingBox()).y < (await page.getByRole('heading', { name: 'Comparisons', exact: true }).boundingBox()).y);
  if (process.env.EVALS_SCREENSHOTS) await page.screenshot({ path: path.join(process.env.EVALS_SCREENSHOTS, 'prompt-tree.png') });
  await promptSection.getByRole('button', { name: 'Open Code prompt', exact: true }).click();
  const codeInspector = page.getByRole('dialog', { name: 'Code prompt', exact: true });
  await expect(codeInspector.getByLabel('Output prompt').locator('option')).toHaveCount(1);
  await expect(codeInspector.locator('pre').first()).toHaveText(variationPrompt.versions[0].stages.alternative);
  await expect(codeInspector).toContainText('Expression: 100% code / 0% natural language');
  await page.keyboard.press('Escape');
  await promptSection.getByRole('button', { name: 'Open Shared baseline prompt', exact: true }).click();
  const inspector = page.getByRole('dialog', { name: 'Shared baseline prompt', exact: true });
  await expect(inspector.getByLabel('Output prompt').locator('option')).toHaveCount(3);
  await inspector.getByLabel('Output prompt').selectOption('baseline-3:generate');
  await expect(inspector.locator('pre').first()).toHaveText(originalPrompt);
  await inspector.getByRole('button', { name: 'Edit and relaunch', exact: true }).click();
  let editor = page.getByRole('dialog', { name: 'Edit prompt and relaunch' });
  await expect(editor.getByRole('textbox', { name: 'Prompt alternative' })).toHaveValue(originalPrompt);
  await editor.getByRole('textbox', { name: 'Prompt alternative' }).fill('Cancelled draft');
  await editor.getByRole('button', { name: 'Cancel', exact: true }).click();
  assert.equal((await api(e + '/runs')).length, beforeRelaunchRuns.length);
  await inspector.getByRole('button', { name: 'Edit and relaunch', exact: true }).click();
  editor = page.getByRole('dialog', { name: 'Edit prompt and relaunch' });
  await editor.getByRole('textbox', { name: 'Prompt alternative' }).fill('{{unknown_variable}}');
  await expect(editor.getByRole('button', { name: 'Launch new attempt', exact: true })).toBeDisabled();
  assert((await editor.getByRole('textbox', { name: 'Prompt alternative' }).boundingBox()).width > 650, 'Prompt editor should use the drawer width');
  const editedPrompt = originalPrompt + '\nMake state ownership explicit.';
  await editor.getByRole('textbox', { name: 'Prompt alternative' }).fill(editedPrompt);
  if (process.env.EVALS_SCREENSHOTS) await page.screenshot({ path: path.join(process.env.EVALS_SCREENSHOTS, 'experiment-relaunch-editor.png') });
  await editor.getByRole('button', { name: 'Launch new attempt', exact: true }).click();
  await expect(editor).toHaveCount(0);
  await expect(promptSection.getByRole('status')).toContainText('Attempt 2 launched');
  const updated = await api(e + '/experiments/' + styles.id);
  assert.equal(updated.samples.length, 5); assert.deepEqual(updated.comparisons, styles.comparisons);
  const attempt = updated.samples.find(s => s.relaunchedFrom);
  assert.equal(attempt.relaunchedFrom.sampleId, 'baseline-3'); assert.equal(attempt.number, 3); assert.equal(attempt.attempt, 2);
  assert.equal(attempt.outputs.length, 1);
  const attemptRunId = attempt.outputs[0].runId;
  await expect.poll(async () => (await api(e + '/runs/' + attemptRunId)).status).toBe('finished');
  const attemptRun = await api(e + '/runs/' + attemptRunId);
  assert.equal(attemptRun.cells.length, 1); assert.equal(attemptRun.request.passes, 1);
  assert.equal(attemptRun.prompts[0].stages.alternative, editedPrompt);
  assert.deepEqual(attemptRun.contexts, baseline.contexts); assert.equal(attemptRun.request.model, baseline.request.model);
  for (const original of beforeRelaunchRuns) assert.deepEqual(await api(e + '/runs/' + original.id), original);
  assert.equal((await api(e + '/prompts/' + prompt.id)).versions.length, catalogVersion + 1, 'Editing an attempt must not mutate the source prompt');
  assert.deepEqual(attemptRun.prompts[0].derivation, { parent: { promptId: prompt.id, version: 1 }, kind: 'relaunch' });
  assert.equal(updated.promptTree, undefined, 'No hand-authored tree is needed.');
  await page.reload();
  await expect(promptSection).toContainText('Shared baseline [3 outputs]');
